entries[36074] = { ["name"] = "Gamaschen des schwarzen Sturms", ["text"] = "Wirken in 45 sek.\nReagenzien:\nUnverwüstliches Leder (10), Odem des Windes (8), Geschmeidiger dicker Balg (2), Runenfaden\nGamaschen des schwarzen Sturms\nWird beim Aufheben gebunden\nBeine Leder\n132 Rüstung\n+13 Beweglichkeit\n+20 Ausdauer\nHaltbarkeit 75 / 75\n45\nBenötigt Elementarlederverarbeitung\nAnlegen: Erhöht die Trefferwertung um 10.\nAnlegen: Erhöht die Angriffskraft um 32." }
entries[36075] = { ["name"] = "Wildfedergamaschen", ["text"] = "Wirken in 45 sek.\nReagenzien:\nUnverwüstliches Leder (10), Leichte Feder (5), Wildranke (4), Geschmeidiger dicker Balg (2), Runenfaden\nWildfedergamaschen\nWird beim Aufheben gebunden\nBeine Leder\n132 Rüstung\n+16 Ausdauer\n+11 Intelligenz\n+12 Willenskraft\nHaltbarkeit 75 / 75\n45\nBenötigt Stammeslederverarbeitung\nAnlegen: Erhöht die Zaubermacht um 21." }
entries[36076] = { ["name"] = "Gamaschen des Drachenschlags", ["text"] = "Wirken in 45 sek.\nReagenzien:\nUnverwüstliches Leder (10), Abgenutzte Drachenschuppe (10), Geschmeidiger dicker Balg (2), Runenfaden\nGamaschen des Drachenschlags\nWird beim Aufheben gebunden\nBeine Kette\n272 Rüstung\n+18 Ausdauer\n+11 Intelligenz\nHaltbarkeit 90 / 90\n45\nBenötigt Drachenlederverarbeitung\nAnlegen: Erhöht die kritische Trefferwertung um 12.\nAnlegen: Erhöht die Angriffskraft um 24.\nAnlegen: Stellt alle 5 Sek. 5 Mana wieder her." }
entries[36077] = { ["name"] = "Brustplatte des Ursturms", ["text"] = "Wirken in 45 sek.\nReagenzien:\nSchweres Knotenhautleder (4), Urluft (2), Urerde (2), Runenfaden (2)\nBrustplatte des Ursturms\nWird beim Aufheben gebunden\nBrust Leder\n255 Rüstung\n+30 Beweglichkeit\n+27 Ausdauer\nHaltbarkeit 100 / 100\n65\nBenötigt Elementarlederverarbeitung\nAnlegen: Erhöht die Trefferwertung um 17.\nAnlegen: Erhöht die Angriffskraft um 60." }
