entries[36640] = { ["name"] = "Arkanschild", ["text"] = "5 Mana 30 Meter Reichweite\nSofort 10 sek. Abklingzeit\nUmgibt den Zaubernden mit 3 Kugeln arkaner Energie, die eine Chance von 50% haben, Nahkampf- oder Distanzangreifer zu treffen und 2 Schaden zu verursachen. Jedes Mal, wenn der Blitzschlagschild zuschlägt, löst sich eine Kugel arkaner Energie auf. Auf diese Weise erlischt der Schild nach 10 min oder nachdem er 3-mal zugeschlagen hat.\n(Procchance: 50%)" }
entries[36642] = { ["name"] = "Verbannung aus Shattrath", ["text"] = "40 Meter Reichweite\nWirken in 1 sek.\nVerbannt einen Feind und verhindert damit jegliche Aktion, macht es aber bis zu 7 sec lang unverwundbar. Es kann immer nur jeweils ein Ziel verbannt werden." }
